-- ── Query 1 ────────────────────────────────────────────────────────────
SELECT     REPORT_DATE as \"Period Date\",     PERIOD_MONTH as \"Period Month\",     PERIOD_START_DATE as \"Period Start Date\",     PERIOD_END_DATE as \"Period End Date\",     TRAN_CODE as \"Tran Code\",     CASE TRAN_CODE         WHEN  1  THEN '01 - Net Sales (retail and cost)'         WHEN  2  THEN '02 - Net Sales VAT Exclusive'         WHEN  3  THEN '03 - Non-Inventory Sales/Returns'         WHEN  4  THEN '04 - Customer Returns (retail and cost)'         WHEN  5  THEN '05 - Non-Inventory VAT Exclusive'         WHEN  6  THEN '06 - Deal Income (sales-related)'         WHEN  7  THEN '07 - Deal Income (non-sales-related)'         WHEN  8  THEN '08 - Fixed Deal Income'         WHEN 11  THEN '11 - Markup (retail only)'         WHEN 12  THEN '12 - Markup Cancel (retail only)'         WHEN 13  THEN '13 - Permanent Markdown (retail only)'         WHEN 14  THEN '14 - Markdown Cancel (retail only)'         WHEN 15  THEN '15 - Promotional Markdown (retail only)'         WHEN 16  THEN '16 - Clearance Markdown (retail only)'         WHEN 20  THEN '20 - Purchases (retail and cost)'         WHEN 22  THEN '22 - Inventory Adjustment'         WHEN 23  THEN '23 - Inventory Adjustment COGS'         WHEN 24  THEN '24 - Return to Vendor (retail and cost)'         WHEN 27  THEN '27 - Intercompany Transfer Out'         WHEN 28  THEN '28 - Intercompany Transfer In'         WHEN 30  THEN '30 - Transfer Out (retail and cost)'         WHEN 31  THEN '31 - Transfer In (retail and cost)'         WHEN 37  THEN '37 - GL Journal Entry Debit'         WHEN 38  THEN '38 - GL Journal Entry Credit'         WHEN 60  THEN '60 - Employee Discount (retail only)'         WHEN 63  THEN '63 - GL Manual Debit'         WHEN 64  THEN '64 - GL Manual Credit'         WHEN 70  THEN '70 - Cost Variance (WAC recalculation)'         WHEN 80  THEN '80 - Stock Count Adjustment (retail)'         WHEN 81  THEN '81 - Stock Count Adjustment (cost)'         WHEN 88  THEN '88 - VAT Sales'         ELSE          'Tran Code ' || TO_CHAR(TRAN_CODE)     END                                                   AS \"Tran Code Description\",     CASE         WHEN TRAN_CODE IN (1,2,4)       THEN 'NET SALES'         WHEN TRAN_CODE = 20             THEN 'PURCHASES'         WHEN TRAN_CODE IN (30,31)       THEN 'TRANSFERS'         WHEN TRAN_CODE IN (27,28)       THEN 'INTERCOMPANY TRANSFERS'         WHEN TRAN_CODE = 24             THEN 'RETURN TO VENDOR'         WHEN TRAN_CODE IN (22,23)       THEN 'INVENTORY ADJUSTMENT'         WHEN TRAN_CODE IN (13,14,15,16) THEN 'MARKDOWNS'         WHEN TRAN_CODE IN (11,12)       THEN 'MARKUPS'         WHEN TRAN_CODE IN (6,7,8)       THEN 'DEAL INCOME'         WHEN TRAN_CODE IN (37,38,63,64) THEN 'GL JOURNAL ENTRIES'         WHEN TRAN_CODE = 60             THEN 'EMPLOYEE DISCOUNT'         WHEN TRAN_CODE = 70             THEN 'COST VARIANCE'         WHEN TRAN_CODE IN (80,81)       THEN 'STOCK COUNT ADJUSTMENTS'         ELSE                                 'OTHER'     END                                                   AS \"Stock Ledger Category\",     CASE         WHEN TRAN_CODE IN (37,38,63,64)         THEN 'REQUIRED - GL_REF_NO must not be NULL'         WHEN TRAN_CODE IN (1,4,20,24,30,31)         THEN 'EXPECTED - key transaction type'         ELSE 'OPTIONAL'     END                                                   AS \"GL Ref Requirement\",     CASE         WHEN TRAN_CODE IN (37,38,63,64,22,23)         THEN 'TOTAL_COST required'         WHEN TRAN_CODE IN (1,4,20,24,27,30,31,37,38)         THEN 'TOTAL_COST required'         WHEN TRAN_CODE IN (11,12,13,14,15,16,60,80,81)         THEN 'TOTAL_RETAIL required'         ELSE 'Both TOTAL_COST and TOTAL_RETAIL required'     END                                                   AS \"Cost Retail Rule\",     DEPT_NO,     DEPT_NAME as \"Department Name\",     ACCOUNTING_METHOD as \"Account Method\",     CASE ACCOUNTING_METHOD         WHEN 1 THEN 'Cost Method'         WHEN 2 THEN 'Retail Method'     END                                                   AS \"Accounting Method Description\",     LOCATION,     LOC_TYPE as \"Location Type\",     SOURCE_PROGRAM as \"Source Program\",     TRANSACTION_COUNT as \"Transaction Count\",     ROUND(TOTAL_COST_RAW,    2)                           AS \"Total Cost\",     ROUND(TOTAL_RETAIL_RAW,  2)                           AS \"Total Retail\",     ROUND(TOTAL_UNITS_RAW,   2)                           AS \"Total Units\",     ROUND(AVG_UNIT_COST_RAW, 4)                           AS \"Average Unit Cost\",     GL_REF_COUNT,     NO_GL_REF_COUNT,     NULL_COST_COUNT,     NULL_RETAIL_COUNT,     CASE WHEN TRANSACTION_COUNT &gt; 0          THEN ROUND(GL_REF_COUNT * 100.0 / TRANSACTION_COUNT, 2)     END                                                   AS \"GL Ref Coverage Percentage\",     FIRST_TRAN_DATE,     LAST_TRAN_DATE,     CASE         WHEN TRAN_CODE IN (37,38,63,64) AND NO_GL_REF_COUNT &gt; 0         THEN 'FAIL: GL_REF_NO required; '              || TO_CHAR(NO_GL_REF_COUNT) || ' records missing'         WHEN TRAN_CODE IN (22,23) AND NULL_COST_COUNT &gt; 0         THEN 'FAIL: TOTAL_COST required for codes 22/23; '              || TO_CHAR(NULL_COST_COUNT) || ' records NULL'         WHEN TRAN_CODE IN (11,12,13,14,15,16,60,80,81) AND NULL_RETAIL_COUNT &gt; 0         THEN 'FAIL: TOTAL_RETAIL required for this tran code; '              || TO_CHAR(NULL_RETAIL_COUNT) || ' records NULL'         WHEN TRAN_CODE IN (1,4,20,24,27,30,31) AND NULL_COST_COUNT &gt; 0         THEN 'WARNING: TOTAL_COST expected; '              || TO_CHAR(NULL_COST_COUNT) || ' records NULL'         WHEN ROUND(TOTAL_COST_RAW, 2) = 0              AND TRANSACTION_COUNT &gt; 0              AND TRAN_CODE IN (1,4,20,22,23,24,30,31)         THEN 'WARNING: Zero total cost on cost-based tran code'         WHEN NO_GL_REF_COUNT &gt; 0         THEN 'REVIEW: ' || TO_CHAR(NO_GL_REF_COUNT)              || ' transactions missing GL_REF_NO'         ELSE 'PASS'     END                                                   AS \"Control Status\",     CASE         WHEN TRAN_CODE IN (37,38,63,64) AND NO_GL_REF_COUNT &gt; 0         THEN 'Post GL journal entries with GL_REF_NO; repost via GL extract process before period close'         WHEN TRAN_CODE IN (22,23) AND NULL_COST_COUNT &gt; 0         THEN 'Review inventory adjustments with NULL cost; check trandataprocess.ksh logs'         WHEN ROUND(TOTAL_COST_RAW, 2) = 0 AND TRANSACTION_COUNT &gt; 0         THEN 'Reconcile zero-cost transactions with GL team; verify cost data and repost if needed'         WHEN NO_GL_REF_COUNT &gt; 0         THEN 'Run GL extract batch; verify GL Cross Reference for tran code '              || TO_CHAR(TRAN_CODE)         ELSE 'No action required - proceed to period close sign-off'     END                                                   AS \"Recommended Action\" FROM (

-- ── Query 2 ────────────────────────────────────────────────────────────
SELECT         TRUNC(SYSDATE)                                    AS REPORT_DATE,         TRUNC(td.TRAN_DATE, 'MM')                         AS PERIOD_MONTH,         p.START_454_MONTH                                 AS PERIOD_START_DATE,         p.END_454_MONTH                                   AS PERIOD_END_DATE,         td.TRAN_CODE                                      AS TRAN_CODE,         td.DEPT                                           AS DEPT_NO,         d.DEPT_NAME                                       AS DEPT_NAME,         d.PROFIT_CALC_TYPE                                AS ACCOUNTING_METHOD,         td.location                                       AS LOCATION,         td.LOC_TYPE                                       AS LOC_TYPE,         td.PGM_NAME                                       AS SOURCE_PROGRAM,         COUNT(*)                                          AS TRANSACTION_COUNT,         SUM(NVL(td.TOTAL_COST,   0))                      AS TOTAL_COST_RAW,         SUM(NVL(td.TOTAL_RETAIL, 0))                      AS TOTAL_RETAIL_RAW,         SUM(NVL(td.UNITS,        0))                      AS TOTAL_UNITS_RAW,         AVG(NVL(td.AV_COST,      0))                      AS AVG_UNIT_COST_RAW,         COUNT(DISTINCT td.GL_REF_NO)                      AS GL_REF_COUNT,         SUM(CASE WHEN td.GL_REF_NO    IS NULL THEN 1 ELSE 0 END)                                                           AS NO_GL_REF_COUNT,         SUM(CASE WHEN td.TOTAL_COST   IS NULL THEN 1 ELSE 0 END)                                                           AS NULL_COST_COUNT,         SUM(CASE WHEN td.TOTAL_RETAIL IS NULL THEN 1 ELSE 0 END)                                                           AS NULL_RETAIL_COUNT,         MIN(td.TRAN_DATE)                                 AS FIRST_TRAN_DATE,         MAX(td.TRAN_DATE)                                 AS LAST_TRAN_DATE     FROM  MFCS_RDS.RDS_WV_TRAN_DATA            td     JOIN  MFCS_RDS.RDS_WV_DEPS                 d    ON  td.DEPT = d.D