><ds:locale>sys</ds:locale></ds:display_name></ds:display_names><ds:datatype>timestamp</ds:datatype><ds:sourceexpr>\"FIRST_TRAN_DATE\"</ds:sourceexpr><ds:aggr_rule>none</ds:aggr_rule></ds:column><ds:column exclude=\"false\"><ds:name>LAST_TRAN_DATE</ds:name><ds:display_names><ds:display_name><ds:name>LAST_TRAN_DATE</ds:name><ds:locale>sys</ds:locale></ds:display_name></ds:display_names><ds:datatype>timestamp</ds:datatype><ds:sourceexpr>\"LAST_TRAN_DATE\"</ds:sourceexpr><ds:aggr_rule>none</ds:aggr_rule></ds:column><ds:column exclude=\"false\"><ds:name>Control Status</ds:name><ds:display_names><ds:display_name><ds:name>Control Status</ds:name><ds:locale>sys</ds:locale></ds:display_name></ds:display_names><ds:datatype>varchar(101)</ds:datatype><ds:sourceexpr>\"Control Status\"</ds:sourceexpr><ds:aggr_rule>none</ds:aggr_rule></ds:column><ds:column exclude=\"false\"><ds:name>Recommended Action</ds:name><ds:display_names><ds:display_name><ds:name>Recommended Action</ds:name><ds:locale>sys</ds:locale></ds:display_name></ds:display_names><ds:datatype>varchar(102)</ds:datatype><ds:sourceexpr>\"Recommended Action\"</ds:sourceexpr><ds:aggr_rule>none</ds:aggr_rule></ds:column></ds:columns><ds:data-access-mode>auto</ds:data-access-mode></ds:table></ds:outputTables><ds:uiOptions>{\"version\":\"v5.2\",\"outputColumns\":[{\"prepColumnName\":\"Period Date\",\"isUserCalculation\":false},{\"prepColumnName\":\"Period Month\",\"isUserCalculation\":false},{\"prepColumnName\":\"Period Start Date\",\"isUserCalculation\":false},{\"prepColumnName\":\"Period End Date\",\"isUserCalculation\":false},{\"prepColumnName\":\"Tran Code\",\"isUserCalculation\":false},{\"prepColumnName\":\"Tran Code Description\",\"isUserCalculation\":false},{\"prepColumnName\":\"Stock Ledger Category\",\"isUserCalculation\":false},{\"prepColumnName\":\"GL Ref Requirement\",\"isUserCalculation\":false},{\"prepColumnName\":\"Cost Retail Rule\",\"isUserCalculation\":false},{\"prepColumnName\":\"DEPT_NO\",\"isUserCalculation\":false},{\"prepColumnName\":\"Department Name\",\"isUserCalculation\":false},{\"prepColumnName\":\"Account Method\",\"isUserCalculation\":false},{\"prepColumnName\":\"Accounting Method Description\",\"isUserCalculation\":false},{\"prepColumnName\":\"LOCATION\",\"isUserCalculation\":false},{\"prepColumnName\":\"Location Type\",\"isUserCalculation\":false},{\"prepColumnName\":\"Source Program\",\"isUserCalculation\":false},{\"prepColumnName\":\"Transaction Count\",\"isUserCalculation\":false},{\"prepColumnName\":\"Total Cost\",\"isUserCalculation\":false},{\"prepColumnName\":\"Total Retail\",\"isUserCalculation\":false},{\"prepColumnName\":\"Total Units\",\"isUserCalculation\":false},{\"prepColumnName\":\"Average Unit Cost\",\"isUserCalculation\":false},{\"prepColumnName\":\"GL_REF_COUNT\",\"isUserCalculation\":false},{\"prepColumnName\":\"NO_GL_REF_COUNT\",\"isUserCalculation\":false},{\"prepColumnName\":\"NULL_COST_COUNT\",\"isUserCalculation\":false},{\"prepColumnName\":\"NULL_RETAIL_COUNT\",\"isUserCalculation\":false},{\"prepColumnName\":\"GL Ref Coverage Percentage\",\"isUserCalculation\":false},{\"prepColumnName\":\"FIRST_TRAN_DATE\",\"isUserCalculation\":false},{\"prepColumnName\":\"LAST_TRAN_DATE\",\"isUserCalculation\":false},{\"prepColumnName\":\"Control Status\",\"isUserCalculation\":false},{\"prepColumnName\":\"Recommended Action\",\"isUserCalculation\":false}],\"transforms\":[{\"id\":\"1\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"DEPT_NO\"],\"expressionSourceColumns\":[\"DEPT_NO\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"DEPT_NO\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"DEPT_NO\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":null},{\"id\":\"2\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"LOCATION\"],\"expressionSourceColumns\":[\"LOCATION\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"LOCATION\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"LOCATION\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"1\"}],\"recommendations\":[],\"dataSubsetInfos\":{\"queryEditMode\":1,\"filterbarSettings\":{},\"uiSqlStatement\":\"

-- ── Query 3 ────────────────────────────────────────────────────────────
SELECT\\n        TRUNC(SYSDATE)                                    AS REPORT_DATE,\\n        TRUNC(td.TRAN_DATE, 'MM')                         AS PERIOD_MONTH,\\n        p.START_454_MONTH                                 AS PERIOD_START_DATE,\\n        p.END_454_MONTH                                   AS PERIOD_END_DATE,\\n        td.TRAN_CODE                                      AS TRAN_CODE,\\n        td.DEPT                                           AS DEPT_NO,\\n        d.DEPT_NAME                                       AS DEPT_NAME,\\n        d.PROFIT_CALC_TYPE                                AS ACCOUNTING_METHOD,\\n        td.location                                       AS LOCATION,\\n        td.LOC_TYPE                                       AS LOC_TYPE,\\n        td.PGM_NAME                                       AS SOURCE_PROGRAM,\\n        COUNT(*)                                          AS TRANSACTION_COUNT,\\n        SUM(NVL(td.TOTAL_COST,   0))                      AS TOTAL_COST_RAW,\\n        SUM(NVL(td.TOTAL_RETAIL, 0))                      AS TOTAL_RETAIL_RAW,\\n        SUM(NVL(td.UNITS,        0))                      AS TOTAL_UNITS_RAW,\\n        AVG(NVL(td.AV_COST,      0))                      AS AVG_UNIT_COST_RAW,\\n        COUNT(DISTINCT td.GL_REF_NO)                      AS GL_REF_COUNT,\\n        SUM(CASE WHEN td.GL_REF_NO    IS NULL THEN 1 ELSE 0 END)\\n                                                          AS NO_GL_REF_COUNT,\\n        SUM(CASE WHEN td.TOTAL_COST   IS NULL THEN 1 ELSE 0 END)\\n                                                          AS NULL_COST_COUNT,\\n        SUM(CASE WHEN td.TOTAL_RETAIL IS NULL THEN 1 ELSE 0 END)\\n                                                          AS NULL_RETAIL_COUNT,\\n        MIN(td.TRAN_DATE)                                 AS FIRST_TRAN_DATE,\\n        MAX(td.TRAN_DATE)                                 AS LAST_TRAN_DATE\\n    FROM  MFCS_RDS.RDS_WV_TRAN_DATA            td\\n    JOIN  MFCS_RDS.RDS_WV_DEPS                 d    ON  td.DEPT = d.DEPT\\n    LEFT JOIN MFCS_RDS.RDS_WV_PERIOD           p    ON  TRUNC(td.TRAN_DATE) = TRUNC(p.VDATE)\\n    WHERE\\n        td.TRAN_DATE &gt;= ADD_MONTHS(SYSDATE, -3)\\n    GROUP BY\\n        TRUNC(td.TRAN_DATE, 'MM'),\\n        p.START_454_MONTH, p.END_454_MONTH,\\n        td.TRAN_CODE, td.DEPT, d.DEPT_NAME,\\n        d.PROFIT_CALC_TYPE, td.location, td.LOC_TYPE, td.PGM_NAME\\n)\\nORDER BY 2, 5, 9, 14\"},\"editorCurrentState\":false,\"joins\":{\"tables\":[]}}</ds:uiOptions><ds:version>v5</ds:version></ds:datasetImportOptions>","business-model":"\"\"","active":true,"custom-attrs":"{\"src_parquet_verified\":\"true\"}","description":"External dataset","display-name":"Manual Query","locale":"sys","is-user-striped":false,"file-length":0,"type":"sql","properties-last-modified":"2026-08-03T11:55:09.660+0000","connection-namespace":"disadmin_disadmin_APPID","private-connection":false,"credential-exists":true,"connection-name":"Remote RDS MFCS Connection","provider-type":"db","provider-name":"oracle","sso-enabled":false,"datamodelname":"'ReCommon'.'RPT_057_RMS_vs_GL_Trans_Control'","parent-namespace":"ReCommon","parent-name":"RPT_057_RMS_vs_GL_Trans_Control","data-access-mode":"auto","is-data-cacheable":true,"checkpoint-metadata-stale":false,"owner-guid":"ReCommon","is-temporary":false},"datasetType":"EMBEDDED","datamodelTwoPartName":"'ReCommon'.'RPT_057_RMS_vs_GL_Trans_Control'"}
